import { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';
import { useNavigate } from 'react-router-dom';

import { Heading } from 'components/UI';
import { useMediaQuery } from 'hooks';
import { StyledSectionsContainer } from 'pages/pillars/ValueCreation/CommercialResults/components/Sections/PerformanceSection/PerformanceSection.styles';
import { StyledMainContainer } from 'shared/Styles';
import { boldRichTextValues } from 'utils/i18n/richTextValues';

import { marketShareWaterfallConfig } from '../../../config';
import { StyledPerformanceToolContent } from '../../../PerformanceTool.styles';
import { DataGovernanceBanner } from '../../DataGovernaceBanner/DataGovernanceBanner';
import {
  BigNumbersSection,
  DriversSection,
  LineBarChartsSection,
} from '../../Sections';
import { WaterfallSection } from '../../Sections/Charts/WaterfallSection/WaterfallSection';
import { StyledPerformanceSectionHeader } from '../../Sections/PerformanceSection/PerformanceSection.styles';
import { BIG_NUMBERS_DATA } from './__mocks__/BigNumbers';
import { LINE_BAR_CHARTS_DATA } from './__mocks__/LineBarChart';
import { kpiDrillDownTableMock_principal } from './__mocks__/Table';
import { WATERFALL_DATA } from './__mocks__/Waterfall';
import { SEGMENTED_CONTROL_OPTIONS } from './constants';

const BREW_DAT_DATE = 'June, 2026';
const ANAPLAN_DATE = 'May, 2026';

export const MarketShareOfficial = () => {
  const { formatMessage } = useIntl();
  const navigate = useNavigate();
  const isLargeScreen = useMediaQuery('(min-width: 1440px)');
  const showDrivers = false;
  const waterfallTitle = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.PerformanceTool.market_share_official.waterfallTitle',
      }),
    [formatMessage],
  );
  const lineBarChartsTitle = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.PerformanceTool.market_share_official.lineBarChartsTitle',
      }),
    [formatMessage],
  );

  const title = useMemo(
    () =>
      formatMessage({
        id: 'ValueCreation.PerformanceTool.market_share_official.title',
      }),
    [formatMessage],
  );

  const governanceMessage = useMemo(
    () =>
      formatMessage(
        {
          id: 'ValueCreation.PerformanceTool.market_share.dataGovernanceBanner',
        },
        {
          brewDatDate: BREW_DAT_DATE,
          anaplanDate: ANAPLAN_DATE,
          ...boldRichTextValues,
        },
      ),
    [formatMessage],
  );

  const handleSeeUpdateStatus = useCallback(() => {
    navigate('/performance-tool/value-creation');
  }, [navigate]);

  const waterfallChartsSection = (
    <>
      {showDrivers && <DriversSection title={waterfallTitle} measure="[ % ]" />}

      {!showDrivers && (
        <WaterfallSection
          title={waterfallTitle}
          data={WATERFALL_DATA}
          tableData={kpiDrillDownTableMock_principal}
          loading={false}
          error={null}
          config={marketShareWaterfallConfig}
          variant={isLargeScreen ? 'large' : 'small'}
          segmentedControlOptions={SEGMENTED_CONTROL_OPTIONS}
        />
      )}
    </>
  );

  return (
    <StyledPerformanceToolContent>
      <StyledMainContainer $fullWidth data-testid="performance-section">
        <StyledPerformanceSectionHeader data-testid="performance-section-header">
          <Heading size="H3" data-testid="performance-section-title">
            {title}
          </Heading>
        </StyledPerformanceSectionHeader>
        <DataGovernanceBanner
          message={governanceMessage}
          onSeeUpdateStatus={handleSeeUpdateStatus}
          dataTestId="market-share-v2-data-governance-banner"
        />
        <StyledSectionsContainer>
          <BigNumbersSection
            variant="embedded"
            data={BIG_NUMBERS_DATA}
            loading={false}
            error={null}
            defaultSelected={0}
            title="Market Share Performance"
          />
          <LineBarChartsSection
            title={lineBarChartsTitle}
            measure="[ % ]"
            data={LINE_BAR_CHARTS_DATA}
            loading={false}
            error={null}
            showLineDataLabels
          />
          {waterfallChartsSection}
        </StyledSectionsContainer>
      </StyledMainContainer>
    </StyledPerformanceToolContent>
  );
};
